draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw clouds
  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t)*50, H/2 - 50, 50, 0, 2*Math.PI);
  ctx.fill();

  // draw rain
  ctx.strokeStyle = '#000000';
  ctx.lineWidth = 3;
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.moveTo(Math.sin(t + i)*W/2 + W/2, 0);
    ctx.lineTo(Math.sin(t + i)*W/2 + W/2, H);
    ctx.stroke();
  }

  // draw rainbow
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.arc(W/2, H - 50, 100, 0, Math.PI, false);
  ctx.strokeStyle = '#ff0000';
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H - 50, 90, 0, Math.PI, false);
  ctx.strokeStyle = '#ffa500';
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H - 50, 80, 0, Math.PI, false);
  ctx.strokeStyle = '#ffff00';
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H - 50, 70, 0, Math.PI, false);
  ctx.strokeStyle = '#008000';
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H - 50, 60, 0, Math.PI, false);
  ctx.strokeStyle = '#0000ff';
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H - 50, 50, 0, Math.PI, false);
  ctx.strokeStyle = '#4b0082';
  ctx.stroke();

  // draw sun
  ctx.fillStyle = '#ffff00';
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t)*50, H/2 - 150, 30, 0, 2*Math.PI);
  ctx.fill();

  ctx.restore();
}
